function act11(action,p){if(!allowed11())throw Error('Akses WAMI tidak tersedia.');if(!isLabel10()&&ten.role!=='super'&&['read','blocked'].includes(access8('wami')))throw Error('Sesi ini hanya dapat melihat pengajuan.');if(action==='create'){const m=member10();if(!m.active||!m.contract||m.blocked105)throw Error('Aktivasi dan persetujuan kontrak diperlukan.');const available=tracks11();const selected=(p.keys||[]).map(k=>available.find(t=>t.key===k));if(selected.some(t=>!t))throw Error('Daftar lagu berubah. Pilih kembali.');const quote=offer11();if(p.quote!==JSON.stringify(quote))throw Error('Biaya atau benefit berubah. Tinjau pengajuan kembali.');p={...p,tracks:selected,...quote};}
 const result=Wami11.act(ten,actor11(),action,p,calendar11());if(action==='accepted'){const o=Wami11.init(ten).orders.find(o=>o.id===p.id),r=ten.releases.find(r=>r.id===o.release),track=r?.songs.find(t=>r.id+':'+t.id===o.track);if(track)track.wami11={order:o.id,reference:o.reference,at:ten.now};if(r)r.wami105=r.songs.every(t=>t.wami11)?'registered':'partial';}save10();return result;}
function tag11(o){return pill107(T(...status11[o.status]),o.status==='done'?'green':o.status==='correction'?'amber':'')}
