function picker11(){if(!isLabel10())return;const m=member10();if(!m.active||!m.contract){reviewDialogUI(T('Aktivasi akun diperlukan','Account activation required'),`<p>${T('Lengkapi aktivasi untuk mengajukan pendaftaran WAMI.','Complete activation to submit a WAMI registration.')}</p>${B11(T('Lanjutkan aktivasi','Continue activation'),'activate','','primary')}`);return;}const rows=tracks11().filter(t=>t.live);reviewDialogUI(T('Pilih lagu','Choose tracks'),`<div class="wizard11"><span class="eyebrow107">01 / 03 · ${T('PILIH LAGU','CHOOSE TRACKS')}</span><h2>${T('Mulai dari katalogmu.','Start with your catalogue.')}</h2><p>${T('Pilih satu atau beberapa lagu yang sudah tayang.','Choose one or more live tracks.')}</p><input type="search" id="picker-search11" placeholder="${T('Cari judul atau artis','Search title or artist')}" aria-label="${T('Cari lagu','Search tracks')}"><div class="picklist11">${rows.map(t=>{const o=Wami11.init(ten).orders.find(o=>o.track===t.key),blocked=!!o||t.registered;return `<label class="pickrow11" data-search="${E((t.title+' '+t.artist).toLowerCase())}"><input type="checkbox" name="track11" value="${E(t.key)}" ${blocked?'disabled':''} ${ui11.chosen.includes(t.key)?'checked':''}>${image11(t)}<span><strong>${E(t.title)}</strong><small>${E(t.artist)} · ${E(t.releaseTitle)}</small>${blocked?`<small>${o?T(...status11[o.status]):T('Catatan WAMI tersedia','WAMI record available')}</small>`:''}</span>${o?B11(T('Lihat pengajuan','View request'),'detail',o.id,'text'):''}</label>`}).join('')||`<p>${T('Belum ada lagu tayang yang dapat dipilih.','No live tracks are available yet.')}</p>`}</div><footer class="actions107">${B11(T('Tutup','Close'),'close','','text')}${B11(T('Lanjutkan','Continue'),'review-selection','','primary')}</footer><p class="error11" role="alert"></p></div>`);}
