 if(action==='ready')body=`<p>${T('Periksa data lagu serta kelengkapan dokumen untuk pendaftaran.','Review track details and registration documents.')}</p>${checked}`;
 if(action==='web'||action==='documents')body=`<p>${action==='web'?T('Pastikan pendaftaran sudah dikirim melalui website WAMI.','Make sure the registration was sent on the WAMI website.'):T('Pastikan dokumen pendaftaran sudah dikirim melalui email.','Make sure the registration documents were emailed.')}</p>${checked}`;
 if(action==='correction')body=`<label>${T('Perlu ditindaklanjuti oleh','Action required from')}<select name="target"><option value="label">Label</option><option value="staff">${T('Petugas','Staff')}</option></select></label>${note}<p>${T('Catatan untuk label akan terlihat di pengajuannya. Perbaikan tidak membuat tagihan baru.','Label correction notes appear on their request. Corrections do not create a new charge.')}</p>`;
